/**
 * 与 map_*_shared.json 对齐的剧情地图配置子集（客户端 MVP）。
 */

export type StoryEventType = 'dialog' | 'task' | 'battle' | 'teleport';

export interface StoryRequirement {
    type: string;
    taskId?: number;
}

export interface StoryEffect {
    action: string;
    taskId?: number;
    toMapId?: number;
    toX?: number;
    toY?: number;
}

export interface StoryNpcEventServer {
    requirements: StoryRequirement[];
    effects: StoryEffect[];
    battleRef?: string;
}

export interface StoryNpcEventClient {
    dialogueScriptId?: string;
    choiceScriptId?: string;
    taskUiHint?: string;
    markerHint?: string;
}

export interface StoryNpcEvent {
    eventId: string;
    eventType: StoryEventType;
    eventTypeDesc?: string;
    order: number;
    server: StoryNpcEventServer;
    client: StoryNpcEventClient;
}

export interface StoryNpcDef {
    npcUid: string;
    npcName?: string;
    prefabKey?: string;
    x?: number;
    y?: number;
    events: StoryNpcEvent[];
}

export interface StoryDialogueScript {
    speaker: string;
    lines: string[];
}

export interface StoryChoiceOption {
    id: string;
    text: string;
    npcReply?: string;
    systemTip?: string;
    forcedResult?: string;
}

export interface StoryChoiceScript {
    title: string;
    options: StoryChoiceOption[];
}

export interface StoryMapClientBlock {
    dialogueScripts: Record<string, StoryDialogueScript>;
    choiceScripts: Record<string, StoryChoiceScript>;
}

export interface StoryMapJson {
    configVersion?: string;
    mapId?: number;
    mapCode?: string;
    mapName?: string;
    server?: {
        antiCheat?: {
            maxInteractDistance?: number;
        };
    };
    client: StoryMapClientBlock;
    npcs: StoryNpcDef[];
}
